/**
 * Marker of every Markdown file generated by agentplugged: the first line, or the line right after
 * the frontmatter when the file has one.
 */
export const GENERATED_HEADER =
  "<!-- Generated by agentplugged. Do not edit: changes are overwritten. -->";
/** Same marker for files whose syntax uses `#` comments. */
export const GENERATED_HEADER_HASH =
  "# Generated by agentplugged. Do not edit: changes are overwritten.";

export const BLOCK_BEGIN = "<!-- agentplugged:begin -->";
export const BLOCK_END = "<!-- agentplugged:end -->";

/** Byte-order mark removed and line endings normalised, so a CRLF checkout is not a change. */
export function normalizeText(text: string): string {
  return (text.startsWith("\uFEFF") ? text.slice(1) : text).replace(/\r\n/g, "\n");
}

export interface Frontmatter {
  /** YAML between the two `---` lines, without them. */
  readonly yaml: string;
  /** Everything after the closing `---` line. */
  readonly body: string;
}

/** Splits a normalised Markdown text into frontmatter and body; undefined without frontmatter. */
export function splitFrontmatter(text: string): Frontmatter | undefined {
  if (!text.startsWith("---\n")) return undefined;
  const match = /\n---[ \t]*(?:\n|$)/.exec(text.slice(3));
  if (!match) return undefined;
  const end = 3 + match.index;
  return { yaml: text.slice(4, end + 1), body: text.slice(end + match[0].length) };
}

/** Puts the header right after the frontmatter, or at the top when there is none. */
export function withGeneratedHeader(text: string): string {
  const normalized = normalizeText(text);
  const parts = splitFrontmatter(normalized);
  if (parts === undefined) return `${GENERATED_HEADER}\n${normalized}`;
  return `---\n${parts.yaml}---\n${GENERATED_HEADER}\n${parts.body}`;
}

function startsWithHeader(text: string, header: string): boolean {
  return text === header || text.startsWith(`${header}\n`);
}

/** True when the file was generated by agentplugged, and may therefore be rewritten. */
export function isGenerated(content: string, header: string = GENERATED_HEADER): boolean {
  const text = normalizeText(content);
  if (startsWithHeader(text, header)) return true;
  if (header !== GENERATED_HEADER) return false;
  const parts = splitFrontmatter(text);
  return parts !== undefined && startsWithHeader(parts.body, header);
}

export function hasPointerBlock(content: string): boolean {
  return content.includes(BLOCK_BEGIN);
}

/**
 * How the block of a creator's instruction file reaches the constitution: `read` asks the tool to
 * read it, `import` loads it with the `@path` syntax of tools that support imports (Claude Code).
 */
export type PointerStyle = "read" | "import";

function pointerLines(target: string, style: PointerStyle): string[] {
  if (style === "import") {
    return [
      "This project uses the AgentPlugged method. Its constitution is imported below.",
      `@${target}`,
    ];
  }
  return [`This project uses the AgentPlugged method. Read and follow \`${target}\`.`];
}

export function pointerBlock(target: string, style: PointerStyle = "read"): string {
  return [BLOCK_BEGIN, ...pointerLines(target, style), BLOCK_END].join("\n");
}

/**
 * Rewrites only the content between the markers of an existing pointer block when it does not
 * point to `target`. Returns undefined when the block is already right or has no end marker.
 */
export function updatePointerBlock(
  content: string,
  target: string,
  style: PointerStyle = "read",
): string | undefined {
  const start = content.indexOf(BLOCK_BEGIN);
  if (start === -1) return undefined;
  const bodyStart = start + BLOCK_BEGIN.length;
  const bodyEnd = content.indexOf(BLOCK_END, bodyStart);
  if (bodyEnd === -1) return undefined;
  const lines = pointerLines(target, style);
  const expected = `\n${lines.join("\n")}\n`;
  if (content.slice(bodyStart, bodyEnd).replace(/\r\n/g, "\n") === expected) return undefined;
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  return `${content.slice(0, bodyStart)}${eol}${lines.join(eol)}${eol}${content.slice(bodyEnd)}`;
}

/**
 * Appends the pointer block at the end of a creator's file. Existing bytes are kept as they
 * are, and the block follows the file's line-ending style.
 */
export function appendPointerBlock(
  content: string,
  target: string,
  style: PointerStyle = "read",
): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const block = pointerBlock(target, style).replace(/\n/g, eol);
  if (normalizeText(content).trim() === "") return `${content}${block}${eol}`;
  const separator = content.endsWith("\n") ? eol : `${eol}${eol}`;
  return `${content}${separator}${block}${eol}`;
}

/**
 * The creator's instruction file with its pointer block present and right: added once at the end,
 * or refreshed between its markers. Undefined when nothing has to change. Shared by `init` and
 * `sync`.
 */
export function withPointerBlock(
  content: string,
  target: string,
  style: PointerStyle = "read",
): string | undefined {
  // A creator's file that already imports the constitution itself gets no block of ours, and
  // loses the one an earlier version added: the constitution is never imported twice.
  if (style === "import" && importsOutsideBlock(content, target)) {
    return removePointerBlock(content);
  }
  if (hasPointerBlock(content)) return updatePointerBlock(content, target, style);
  return appendPointerBlock(content, target, style);
}

/**
 * True when the creator's file, outside our block, imports `target` with the `@path` syntax
 * (`@AGENTS.md`, `@./AGENTS.md`, alone on its line or within a sentence), so the tool already
 * loads it. What the tool does not read as an import is left out: fenced code blocks, inline
 * code spans and HTML comments. A begin marker without its end counts as no import (the file is
 * then a conflict, never rewritten).
 */
export function importsOutsideBlock(content: string, target: string): boolean {
  const start = content.indexOf(BLOCK_BEGIN);
  if (start !== -1 && content.indexOf(BLOCK_END, start) === -1) return false;
  const text = normalizeText(removePointerBlock(content) ?? content).replace(
    /<!--[\s\S]*?-->/g,
    " ",
  );
  const escaped = target.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  // The path ends with the line, a blank or a punctuation mark that ends a sentence (`@AGENTS.md.`).
  const token = new RegExp(`(?:^|\\s)@(?:\\./)?${escaped}(?=$|\\s|[.,;:!?)](?:$|\\s))`);
  let fence: string | undefined;
  for (const line of text.split("\n")) {
    const marker = /^ {0,3}(`{3,}|~{3,})/.exec(line)?.[1];
    if (fence !== undefined) {
      if (marker !== undefined && marker[0] === fence[0] && marker.length >= fence.length) {
        fence = undefined;
      }
      continue;
    }
    if (marker !== undefined) {
      fence = marker;
      continue;
    }
    if (token.test(line.replace(/`[^`]*`/g, " "))) return true;
  }
  return false;
}

/**
 * The creator's file without its pointer block: the block, its line break and the blank line
 * `appendPointerBlock` put before it are removed. Undefined when there is no complete block.
 */
export function removePointerBlock(content: string): string | undefined {
  const start = content.indexOf(BLOCK_BEGIN);
  if (start === -1) return undefined;
  const end = content.indexOf(BLOCK_END, start);
  if (end === -1) return undefined;
  let after = content.slice(end + BLOCK_END.length);
  if (after.startsWith("\r\n")) after = after.slice(2);
  else if (after.startsWith("\n")) after = after.slice(1);
  let before = content.slice(0, start);
  if (before.endsWith("\r\n\r\n")) before = before.slice(0, -2);
  else if (before.endsWith("\n\n")) before = before.slice(0, -1);
  return `${before}${after}`;
}

/** Instruction files whose tools load the constitution with an `@path` import. */
export const IMPORT_FILES = ["CLAUDE.md", "GEMINI.md"] as const;

/** Style of each instruction file's block. */
export function pointerStyleOf(path: string): PointerStyle {
  return (IMPORT_FILES as readonly string[]).includes(path) ? "import" : "read";
}

/**
 * Content of a `CLAUDE.md` or `GEMINI.md` generated by agentplugged: it imports the constitution,
 * then the other files given (`also`): the creator's root `AGENTS.md`, which Claude Code reads
 * only while no `CLAUDE.md` exists.
 */
export function renderImportFile(target: string, also: readonly string[] = []): string {
  const imports = [target, ...also.filter((path) => path !== target)];
  return `${GENERATED_HEADER}\n${imports.map((path) => `@${path}`).join("\n")}\n`;
}
